/* Cyber Snake Game & Animated Icon Styles */
.juegos-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
  margin-top: 24px;
}

.folder-entry {
  position: relative;
  border: 1px solid var(--line);
  background: var(--panel);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  text-decoration: none;
  color: inherit;
  transition: border-color 0.2s ease, transform 0.2s ease;
  cursor: pointer;
}

.folder-entry:hover {
  border-color: var(--green);
  transform: translateY(-2px);
}

.card-tag {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--green);
  letter-spacing: 0.05em;
}

.folder-entry h4 {
  margin: 0;
  font-family: var(--display);
  font-size: 20px;
  color: var(--paper);
}

.folder-entry p {
  margin: 0;
  font-family: var(--mono);
  font-size: 13px;
  color: var(--muted);
  line-height: 1.6;
}

.card-meta {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--muted);
}

.card-cta {
  margin-top: auto;
  font-family: var(--mono);
  font-size: 12px;
  color: var(--green);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* Animated Interactive Icon Preview */
.snake-preview-icon {
  width: 100%;
  height: 60px;
  background: var(--ink);
  border: 1px solid var(--line);
  position: relative;
  overflow: hidden;
  margin-bottom: 8px;
}

.snake-preview-canvas {
  width: 100%;
  height: 100%;
  display: block;
}

/* Snake Game Modal Overlay */
.snake-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(9, 11, 10, 0.85);
  backdrop-filter: blur(4px);
  z-index: 1000;
  display: grid;
  place-items: center;
  padding: 20px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
}

.snake-modal-overlay.is-active {
  opacity: 1;
  pointer-events: auto;
}

.snake-modal-container {
  width: min(500px, 100%);
  background: var(--panel);
  border: 1px solid var(--green);
  box-shadow: 0 0 30px color-mix(in srgb, var(--green) 20%, transparent);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.snake-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--line);
  padding-bottom: 12px;
}

.snake-title {
  font-family: var(--display);
  font-size: 18px;
  color: var(--green);
  margin: 0;
}

.snake-close-btn {
  background: none;
  border: 1px solid var(--line);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 14px;
  padding: 4px 8px;
  cursor: pointer;
  transition: all 0.2s;
}

.snake-close-btn:hover {
  border-color: var(--green);
  color: var(--green);
}

.snake-stats {
  display: flex;
  justify-content: space-between;
  font-family: var(--mono);
  font-size: 12px;
  color: var(--green);
}

.snake-game-canvas-wrap {
  border: 1px solid var(--line);
  background: var(--ink);
  position: relative;
  aspect-ratio: 1;
}

.snake-canvas {
  width: 100%;
  height: 100%;
  display: block;
}

.snake-controls-hint {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--muted);
  text-align: center;
}

.snake-touch-pad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  max-width: 200px;
  margin: 0 auto;
}

.snake-touch-btn {
  background: var(--ink);
  border: 1px solid var(--line);
  color: var(--green);
  font-family: var(--mono);
  font-size: 16px;
  padding: 12px 0;
  text-align: center;
  cursor: pointer;
  user-select: none;
