import { Model } from '../../js/model.js';
import { View } from '../../js/view.js';
import { Controller } from '../../js/controller.js';

// Cyber Snake Game Module & Animated Interactive Icon
Object.assign(View, {
  renderSnakePreview(container) {
    const preview = document.createElement("div");
    preview.className = "snake-preview-icon";
    const canvas = document.createElement("canvas");
    canvas.className = "snake-preview-canvas";
    canvas.width = 240;
    canvas.height = 60;
    preview.appendChild(canvas);
    container.prepend(preview);

    const ctx = canvas.getContext("2d");
    let snake = [{x: 5, y: 2}, {x: 4, y: 2}, {x: 3, y: 2}, {x: 2, y: 2}];
    let food = {x: 10, y: 2};
    let dx = 1;
    let frame = 0;

    const interval = setInterval(() => {
      if (!document.body.contains(canvas)) {
        clearInterval(interval);
        return;
      }
      frame++;
      if (frame % 10 === 0) {
        const head = { x: snake[0].x + dx, y: snake[0].y };
        if (head.x >= 20 || head.x < 0) {
          dx = -dx;
          head.x += dx * 2;
        }
        snake.unshift(head);
        snake.pop();
      }

      ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--ink').trim() || '#090b0a';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--green-dim').trim() || '#087d2a';
      ctx.strokeStyle = getComputedStyle(document.documentElement).getPropertyValue('--line').trim() || '#2b322d';
      ctx.lineWidth = 0.5;

      for (let x = 0; x < canvas.width; x += 12) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, canvas.height); ctx.stroke();
      }
      for (let y = 0; y < canvas.height; y += 12) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(canvas.width, y); ctx.stroke();
      }

      const green = getComputedStyle(document.documentElement).getPropertyValue('--green').trim() || '#20ef4f';
      ctx.fillStyle = green;
      snake.forEach(part => {
        ctx.fillRect(part.x * 12 + 1, part.y * 12 + 1, 10, 10);
      });

      ctx.fillStyle = '#ef2020';
      ctx.fillRect(food.x * 12 + 1, food.y * 12 + 1, 10, 10);
    }, 80);
  }
});

const originalRenderJuegos = View.renderJuegos;
View.renderJuegos = function(games) {
  originalRenderJuegos.call(this, games);
  const container = document.getElementById("juegos-body");
  if (!container) return;
  const entries = container.querySelectorAll(".folder-entry");
  entries.forEach((entry, index) => {
    const game = games[index];
    if (game && game.id === "snake") {
      this.renderSnakePreview(entry);
      entry.removeAttribute("href");
      entry.removeAttribute("target");
      entry.removeAttribute("rel");
      entry.addEventListener("click", (e) => {
        e.preventDefault();
        Controller.openSnakeModal();
      });
    }
  });
};

Object.assign(Controller, {
  openSnakeModal() {
    let overlay = document.querySelector(".snake-modal-overlay");
    if (!overlay) {
      overlay = document.createElement("div");
      overlay.className = "snake-modal-overlay";
      overlay.innerHTML = `
        <div class="snake-modal-container">
          <div class="snake-header">
            <h3 class="snake-title">CYBER SNAKE // ARCADE</h3>
            <button class="snake-close-btn" type="button">×</button>
          </div>
          <div class="snake-stats">
            <span id="snake-score">SCORE: 0</span>
            <span id="snake-hi">HI: 0</span>
          </div>
          <div class="snake-game-canvas-wrap">
            <canvas class="snake-canvas" id="snake-game-canvas" width="400" height="400"></canvas>
          </div>
          <p class="snake-controls-hint">USE ARROW KEYS / WASD TO NAVIGATE. SPACE TO START / PAUSE.</p>
          <div class="snake-touch-pad">
            <button class="snake-touch-btn snake-btn-up" data-dir="UP">▲</button>
            <button class="snake-touch-btn snake-btn-left" data-dir="LEFT">◀</button>
            <button class="snake-touch-btn snake-btn-down" data-dir="DOWN">▼</button>
            <button class="snake-touch-btn snake-btn-right" data-dir="RIGHT">▶</button>
          </div>
        </div>
      `;
      document.body.appendChild(overlay);

      overlay.querySelector(".snake-close-btn").addEventListener("click", () => {
        this.closeSnakeModal();
      });

      overlay.addEventListener("click", (e) => {
        if (e.target === overlay) this.closeSnakeModal();
      });

      this.initSnakeGameEngine(overlay);
    }
    overlay.classList.add("is-active");
    if (this.snakeGameStart) this.snakeGameStart();
  },

  closeSnakeModal() {
    const overlay = document.querySelector(".snake-modal-overlay");
    if (overlay) overlay.classList.remove("is-active");
    if (this.snakeGamePause) this.snakeGamePause();
  },

  initSnakeGameEngine(overlay) {
    const canvas = overlay.querySelector("#snake-game-canvas");
    const ctx = canvas.getContext("2d");
    const scoreEl = overlay.querySelector("#snake-score");
    const hiEl = overlay.querySelector("#snake-hi");
    const grid = 20;
    const tileCount = canvas.width / grid;

    let snake = [];
    let food = { x: 5, y: 5 };
    let dx = 0;
    let dy = 0;
    let score = 0;
    let hi = parseInt(localStorage.getItem("cyber_snake_hi") || "0", 10);
    hiEl.textContent = `HI: ${hi}`;
    let gameInterval = null;
    let gameState = "START";

    const resetGame = () => {
      snake = [
        { x: 10, y: 10 },
        { x: 9, y: 10 },
        { x: 8, y: 10 }
      ];
      dx = 1;
      dy = 0;
      score = 0;
      scoreEl.textContent = `SCORE: ${score}`;
      spawnFood();
    };

