      snake.forEach((part, index) => {
        ctx.fillStyle = index === 0 ? "#20ef4f" : "#087d2a";
        ctx.fillRect(part.x * grid + 1, part.y * grid + 1, grid - 2, grid - 2);
      });

      if (gameState === "START") {
        ctx.fillStyle = "rgba(9, 11, 10, 0.8)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#20ef4f";
        ctx.font = "16px 'DM Mono', monospace";
        ctx.textAlign = "center";
        ctx.fillText("PRESS SPACE OR TAP TO START", canvas.width / 2, canvas.height / 2);
      } else if (gameState === "OVER") {
        ctx.fillStyle = "rgba(9, 11, 10, 0.85)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#ef2020";
        ctx.font = "bold 20px 'Space Grotesk', sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("GAME OVER", canvas.width / 2, canvas.height / 2 - 15);
        ctx.fillStyle = "#20ef4f";
        ctx.font = "14px 'DM Mono', monospace";
        ctx.fillText("PRESS ENTER / TAP TO RESTART", canvas.width / 2, canvas.height / 2 + 15);
      }
    };

    const update = () => {
      if (gameState !== "PLAYING") return;

      const head = { x: snake[0].x + dx, y: snake[0].y + dy };

      if (head.x < 0 || head.x >= tileCount || head.y < 0 || head.y >= tileCount) {
        gameOver();
        return;
      }

      if (snake.some(part => part.x === head.x && part.y === head.y)) {
        gameOver();
        return;
      }

      snake.unshift(head);

      if (head.x === food.x && head.y === food.y) {
        score += 10;
        scoreEl.textContent = `SCORE: ${score}`;
        if (score > hi) {
          hi = score;
          hiEl.textContent = `HI: ${hi}`;
          localStorage.setItem("cyber_snake_hi", hi);
        }
        spawnFood();
      } else {
        snake.pop();
      }
    };

    const gameOver = () => {
      gameState = "OVER";
      clearInterval(gameInterval);
      draw();
    };

    const startGame = () => {
      if (gameState === "PLAYING") return;
      resetGame();
      gameState = "PLAYING";
      if (gameInterval) clearInterval(gameInterval);
      gameInterval = setInterval(() => {
        update();
        draw();
      }, 100);
    };

    this.snakeGamePause = () => {
      if (gameState === "PLAYING") {
        gameState = "PAUSED";
        clearInterval(gameInterval);
      }
    };

    this.snakeGameStart = () => {
      if (gameState === "START" || gameState === "OVER") {
        startGame();
      } else if (gameState === "PAUSED") {
        gameState = "PLAYING";
        gameInterval = setInterval(() => {
          update();
          draw();
        }, 100);
      }
    };

    window.addEventListener("keydown", (e) => {
      if (!overlay.classList.contains("is-active")) return;
      if (["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", " "].includes(e.key)) {
        e.preventDefault();
      }

      if (e.key === " ") {
        if (gameState === "START" || gameState === "OVER") startGame();
        else if (gameState === "PLAYING") this.snakeGamePause();
        else if (gameState === "PAUSED") this.snakeGameStart();
        return;
      }

      if (e.key === "Enter" && gameState === "OVER") {
        startGame();
        return;
      }

      if (gameState !== "PLAYING") return;

      if ((e.key === "ArrowUp" || e.key === "w" || e.key === "W") && dy === 0) {
        dx = 0; dy = -1;
      } else if ((e.key === "ArrowDown" || e.key === "s" || e.key === "S") && dy === 0) {
        dx = 0; dy = 1;
      } else if ((e.key === "ArrowLeft" || e.key === "a" || e.key === "A") && dx === 0) {
        dx = -1; dy = 0;
      } else if ((e.key === "ArrowRight" || e.key === "d" || e.key === "D") && dx === 0) {
        dx = 1; dy = 0;
      }
    });

    overlay.querySelectorAll(".snake-touch-btn").forEach(btn => {
      btn.addEventListener("click", () => {
        const dir = btn.dataset.dir;
        if (gameState === "START" || gameState === "OVER") {
          startGame();
          return;
        }
        if (gameState !== "PLAYING") return;

        if (dir === "UP" && dy === 0) { dx = 0; dy = -1; }
        if (dir === "DOWN" && dy === 0) { dx = 0; dy = 1; }
        if (dir === "LEFT" && dx === 0) { dx = -1; dy = 0; }
        if (dir === "RIGHT" && dx === 0) { dx = 1; dy = 0; }
      });
    });

    canvas.addEventListener("click", () => {
      if (gameState === "START" || gameState === "OVER") {
        startGame();
      }
    });

    resetGame();
    draw();
  }
});

