          return;
        }
        if (gameState !== "PLAYING") return;

        if (dir === "UP" && dy === 0) { dx = 0; dy = -1; }
        if (dir === "DOWN" && dy === 0) { dx = 0; dy = 1; }
        if (dir === "LEFT" && dx === 0) { dx = -1; dy = 0; }
        if (dir === "RIGHT" && dx === 0) { dx = 1; dy = 0; }
      });
    });

    canvas.addEventListener("click", () => {
      if (gameState === "START" || gameState === "OVER") {
        startGame();
      }
    });

    resetGame();
    draw();
  }
});

