    homeContent.append(badge);

    const miniCanvas = badge.querySelector("#home-snake-mini");
    const mctx = miniCanvas.getContext("2d");
    let msnake = [{x: 2, y: 1}, {x: 1, y: 1}, {x: 0, y: 1}];
    let mdx = 1;
    setInterval(() => {
      if (!document.body.contains(miniCanvas)) return;
      msnake.unshift({ x: msnake[0].x + mdx, y: msnake[0].y });
      if (msnake[0].x >= 7 || msnake[0].x < 0) {
        mdx = -mdx;
        msnake[0].x += mdx * 2;
      }
      msnake.pop();
      mctx.fillStyle = "#090b0a";
      mctx.fillRect(0, 0, 28, 28);
      mctx.fillStyle = "#20ef4f";
      msnake.forEach(p => mctx.fillRect(p.x * 4 + 1, p.y * 4 + 1, 3, 3));
    }, 120);
  }
